BEGIN;
CREATE EXTENSION IF NOT EXISTS pgtap WITH SCHEMA extensions;
SET LOCAL search_path=public,extensions;
SELECT no_plan();
INSERT INTO auth.users(id,email,email_confirmed_at,raw_user_meta_data) VALUES
 ('f1000000-0000-0000-0000-000000000001','hub-owner@example.invalid',now(),'{"name":"Owner","role":"owner"}'),
 ('f1000000-0000-0000-0000-000000000002','hub-manager@example.invalid',now(),'{"name":"Manager","role":"tenant"}'),
 ('f1000000-0000-0000-0000-000000000003','hub-viewer@example.invalid',now(),'{"name":"Viewer","role":"tenant"}'),
 ('f1000000-0000-0000-0000-000000000004','hub-candidate@example.invalid',now(),'{"name":"Candidate","role":"tenant"}'),
 ('f1000000-0000-0000-0000-000000000005','hub-second@example.invalid',now(),'{"name":"Second","role":"owner"}'),
 ('f1000000-0000-0000-0000-000000000006','hub-unconfirmed@example.invalid',null,'{"name":"Unconfirmed","role":"tenant"}');
INSERT INTO public.properties(id,owner_id,name,address,description) VALUES
 ('f2000000-0000-0000-0000-000000000001','f1000000-0000-0000-0000-000000000001','PRIVATE_TITLE','PRIVATE_ADDRESS','PRIVATE_ACCESS_CODE'),
 ('f2000000-0000-0000-0000-000000000002','f1000000-0000-0000-0000-000000000001','UNASSIGNED','SECRET','SECRET');
INSERT INTO public.units(id,property_id,name) VALUES ('f3000000-0000-0000-0000-000000000001','f2000000-0000-0000-0000-000000000001','101');
INSERT INTO public.team_memberships(id,owner_id,email,user_id,role,status) VALUES
 ('f4000000-0000-0000-0000-000000000001','f1000000-0000-0000-0000-000000000001','hub-manager@example.invalid','f1000000-0000-0000-0000-000000000002','manager','active'),
 ('f4000000-0000-0000-0000-000000000002','f1000000-0000-0000-0000-000000000001','hub-viewer@example.invalid','f1000000-0000-0000-0000-000000000003','viewer','active');
INSERT INTO public.team_property_access VALUES
 ('f4000000-0000-0000-0000-000000000001','f2000000-0000-0000-0000-000000000001'),('f4000000-0000-0000-0000-000000000002','f2000000-0000-0000-0000-000000000001');
SELECT set_config('test.listing_values',jsonb_build_object('title','Sunny flat','location','Near the park','description','Public description','monthly_rent','45000','deposit','45000','area','40','available_from',CURRENT_DATE,'contact_name','Anna','photos','[]'::jsonb,'private_secret','NEVER_PUBLIC')::text,true);
CREATE FUNCTION pg_temp.listing_rev() RETURNS integer LANGUAGE sql AS $$SELECT (l->>'revision')::integer FROM jsonb_array_elements(public.property_hub('f2000000-0000-0000-0000-000000000001')->'listings') l WHERE l->>'id'=current_setting('test.listing')$$;
CREATE FUNCTION pg_temp.app_rev() RETURNS integer LANGUAGE sql AS $$SELECT (a->>'revision')::integer FROM jsonb_array_elements(public.recruitment_overview()->'applications') a WHERE a->>'id'=current_setting('test.application')$$;
SELECT ok((SELECT bool_and(relrowsecurity) FROM pg_class WHERE oid IN ('public.property_listings'::regclass,'public.rental_applications'::regclass,'public.recruitment_events'::regclass)),'all new tables use RLS');
SELECT ok(NOT EXISTS(SELECT 1 FROM pg_proc f JOIN pg_namespace n ON n.oid=f.pronamespace WHERE n.nspname='private' AND f.prosecdef AND has_function_privilege('anon',f.oid,'EXECUTE') AND f.proname NOT IN ('public_listing','listing_photo_access','public_property_catalog')),'anonymous private definer surface contains only public snapshot and photo predicate');
SELECT ok(NOT has_table_privilege('anon','public.property_listings','SELECT'),'no anonymous raw listing access');
SELECT ok(NOT has_table_privilege('authenticated','public.rental_applications','SELECT,UPDATE'),'no raw contact or status access');
SELECT ok(NOT has_function_privilege('anon','private.application_snapshot(uuid,boolean)','EXECUTE'),'private contact helper is not callable');
SELECT set_config('request.jwt.claims','{"sub":"f1000000-0000-0000-0000-000000000001"}',true);
SET LOCAL ROLE authenticated;
SELECT set_config('test.listing',public.save_property_listing('f2000000-0000-0000-0000-000000000001',null,null,current_setting('test.listing_values')::jsonb,null)::text,true);
SELECT is(jsonb_array_length(public.property_hub('f2000000-0000-0000-0000-000000000001')->'listings'),1,'owner sees draft in hub');
SELECT throws_ok($$SELECT public.act_on_property_listing(current_setting('test.listing')::uuid,'publish',pg_temp.listing_rev())$$,'23514',NULL,'cannot publish without selected photos');
RESET ROLE;
SELECT set_config('test.public_id',(SELECT public_id::text FROM public.property_listings WHERE id=current_setting('test.listing')::uuid),true);
SELECT set_config('test.photo',current_setting('test.public_id')||'/cover.png',true);
SELECT set_config('request.jwt.claims','{}',true);
SET LOCAL ROLE anon;
SELECT ok(public.public_listing(current_setting('test.public_id')::uuid) IS NULL,'anonymous visitor cannot see draft');
SELECT throws_ok($$SELECT public.property_hub('f2000000-0000-0000-0000-000000000001')$$,'42501',NULL,'anonymous visitor cannot open internal hub');
SELECT throws_ok($$SELECT public.apply_to_listing(current_setting('test.public_id')::uuid,'{}')$$,'42501',NULL,'anonymous cannot submit contacts');
RESET ROLE;
SELECT set_config('request.jwt.claims','{"sub":"f1000000-0000-0000-0000-000000000001"}',true);
SET LOCAL ROLE authenticated;
SELECT lives_ok($$INSERT INTO storage.objects(bucket_id,name) VALUES('listing-photos',current_setting('test.photo'))$$,'owner uploads marketing photo');
SELECT lives_ok($$SELECT public.save_property_listing('f2000000-0000-0000-0000-000000000001',current_setting('test.listing')::uuid,null,current_setting('test.listing_values')::jsonb||jsonb_build_object('photos',jsonb_build_array(current_setting('test.photo'))),pg_temp.listing_rev())$$,'save explicitly selected photo');
SELECT lives_ok($$SELECT public.act_on_property_listing(current_setting('test.listing')::uuid,'publish',pg_temp.listing_rev())$$,'owner publishes');
SELECT throws_ok($$SELECT public.act_on_property_listing(current_setting('test.listing')::uuid,'pause',1)$$,'40001',NULL,'stale publication action fails');
RESET ROLE;
SELECT set_config('request.jwt.claims','{}',true);
SET LOCAL ROLE anon;
SELECT is(public.public_listing(current_setting('test.public_id')::uuid)->'details'->>'title','Sunny flat','anonymous sees published card');
SELECT ok(public.public_listing(current_setting('test.public_id')::uuid)::text NOT LIKE '%PRIVATE_%' AND public.public_listing(current_setting('test.public_id')::uuid)::text NOT LIKE '%NEVER_PUBLIC%' AND public.public_listing(current_setting('test.public_id')::uuid)::text NOT LIKE '%owner_id%','public snapshot excludes private fields identities and arbitrary inputs');
SELECT is((SELECT count(*) FROM storage.objects WHERE bucket_id='listing-photos'),1::bigint,'anonymous sees only approved marketing photo');
RESET ROLE;
SELECT set_config('request.jwt.claims','{"sub":"f1000000-0000-0000-0000-000000000002","user_metadata":{"role":"admin"}}',true);
SET LOCAL ROLE authenticated;
SELECT is(public.property_hub('f2000000-0000-0000-0000-000000000001')->'property'->>'role','manager','personal tenant role does not block selected manager hub');
SELECT throws_ok($$SELECT public.property_hub('f2000000-0000-0000-0000-000000000002')$$,'42501',NULL,'unselected property denied');
SELECT throws_ok($$SELECT public.act_on_property_listing(current_setting('test.listing')::uuid,'pause',pg_temp.listing_rev())$$,'42501',NULL,'manager metadata cannot publish or hide');
RESET ROLE;
SELECT set_config('request.jwt.claims','{"sub":"f1000000-0000-0000-0000-000000000006"}',true);
SET LOCAL ROLE authenticated;
SELECT throws_ok($$SELECT public.apply_to_listing(current_setting('test.public_id')::uuid,'{"name":"No confirmation","phone":"1234567","consent":true}')$$,'42501',NULL,'unconfirmed applicant denied');
RESET ROLE;
SELECT set_config('request.jwt.claims','{"sub":"f1000000-0000-0000-0000-000000000004"}',true);
SET LOCAL ROLE authenticated;
SELECT throws_ok($$SELECT public.property_hub('f2000000-0000-0000-0000-000000000001')$$,'42501',NULL,'registered visitor still has no internal access');
SELECT throws_ok($$SELECT public.apply_to_listing(current_setting('test.public_id')::uuid,'{"name":"Candidate","phone":"1234567"}')$$,'22023',NULL,'contact sharing requires consent');
SELECT set_config('test.application',public.apply_to_listing(current_setting('test.public_id')::uuid,'{"name":"Candidate","phone":"1234567","consent":true,"email":"forged@example.invalid"}')::text,true);
SELECT is(public.apply_to_listing(current_setting('test.public_id')::uuid,'{"name":"Duplicate","phone":"1234567","consent":true}')::text,current_setting('test.application'),'duplicate submission returns original application');
SELECT is(jsonb_array_length(public.recruitment_overview()->'applications'),1,'candidate sees own application');
SELECT is(public.recruitment_overview()->'applications'->0->>'email','hub-candidate@example.invalid','email taken from verified auth record');
SELECT ok(public.recruitment_overview()->'applications'->0->>'operator_note' IS NULL,'candidate cannot read internal note');
SELECT throws_ok($$SELECT public.act_on_rental_application(current_setting('test.application')::uuid,'shortlist',pg_temp.app_rev())$$,'42501',NULL,'candidate cannot self shortlist');
RESET ROLE;
SELECT set_config('request.jwt.claims','{"sub":"f1000000-0000-0000-0000-000000000005"}',true);
SET LOCAL ROLE authenticated;
SELECT is(jsonb_array_length(public.recruitment_overview()->'applications'),0,'other account cannot read first applicant');
SELECT set_config('test.second',public.apply_to_listing(current_setting('test.public_id')::uuid,'{"name":"Second","phone":"7654321","consent":true}')::text,true);
SELECT throws_ok($$SELECT public.act_on_rental_application(current_setting('test.application')::uuid,'withdraw',1)$$,'42501',NULL,'other user cannot withdraw first applicant');
RESET ROLE;
SELECT set_config('request.jwt.claims','{"sub":"f1000000-0000-0000-0000-000000000003"}',true);
SET LOCAL ROLE authenticated;
SELECT is(jsonb_array_length(public.property_hub('f2000000-0000-0000-0000-000000000001')->'applications'),0,'viewer sees no applicant contacts');
SELECT is((public.property_hub('f2000000-0000-0000-0000-000000000001')->>'application_count')::integer,2,'viewer sees aggregate pipeline count');
SELECT throws_ok($$SELECT public.act_on_rental_application(current_setting('test.application')::uuid,'shortlist',1)$$,'42501',NULL,'viewer cannot edit pipeline');
RESET ROLE;
SELECT set_config('request.jwt.claims','{"sub":"f1000000-0000-0000-0000-000000000002"}',true);
SET LOCAL ROLE authenticated;
SELECT lives_ok($$SELECT public.act_on_rental_application(current_setting('test.application')::uuid,'schedule',1,jsonb_build_object('showing_at',now()+interval '1 day','public_note','Meet at entrance','operator_note','INTERNAL_CANDIDATE_NOTE'))$$,'manager schedules showing');
SELECT throws_ok($$SELECT public.act_on_rental_application(current_setting('test.application')::uuid,'accept',2,'{}')$$,'42501',NULL,'manager cannot create financial agreement');
SELECT throws_ok($$SELECT public.act_on_rental_application(current_setting('test.application')::uuid,'shortlist',1)$$,'40001',NULL,'stale candidate revision rejected');
RESET ROLE;
SELECT set_config('request.jwt.claims','{"sub":"f1000000-0000-0000-0000-000000000004"}',true);
SET LOCAL ROLE authenticated;
SELECT is(public.recruitment_overview()->'applications'->0->>'status','showing','candidate sees showing');
SELECT ok(public.recruitment_overview()::text NOT LIKE '%INTERNAL_CANDIDATE_NOTE%','private note never leaks to candidate');
RESET ROLE;
SELECT set_config('request.jwt.claims','{"sub":"f1000000-0000-0000-0000-000000000001"}',true);
SET LOCAL ROLE authenticated;
SELECT public.save_property_listing('f2000000-0000-0000-0000-000000000001',current_setting('test.listing')::uuid,null,current_setting('test.listing_values')::jsonb||jsonb_build_object('monthly_rent','50000','photos',jsonb_build_array(current_setting('test.photo'))),pg_temp.listing_rev());
SELECT is(public.public_listing(current_setting('test.public_id')::uuid)->'details'->>'monthly_rent','45000','editing draft does not silently change published terms');
SELECT set_config('test.lease',public.act_on_rental_application(current_setting('test.application')::uuid,'accept',2,jsonb_build_object('start_date',CURRENT_DATE,'end_date',CURRENT_DATE+365,'payment_due_day',15))::text,true);
SELECT is(public.act_on_rental_application(current_setting('test.application')::uuid,'accept',2,'{}')::text,current_setting('test.lease'),'duplicate accept returns same draft');
RESET ROLE;
SELECT is((SELECT status FROM public.lease_agreements WHERE id=current_setting('test.lease')::uuid),'draft','selection creates draft only');
SELECT is((SELECT monthly_payment FROM public.lease_agreements WHERE id=current_setting('test.lease')::uuid),45000::numeric,'draft uses offered rent not later edits');
SELECT is((SELECT (contract_details->>'depositAmount')::numeric FROM public.lease_agreements WHERE id=current_setting('test.lease')::uuid),45000::numeric,'deposit follows offer');
SELECT is((SELECT user_id FROM public.tenants WHERE id=(SELECT tenant_id FROM public.lease_agreements WHERE id=current_setting('test.lease')::uuid)),'f1000000-0000-0000-0000-000000000004'::uuid,'tenant linked to verified applicant');
SELECT is((SELECT count(*) FROM public.rent_charges WHERE agreement_id=current_setting('test.lease')::uuid),0::bigint,'selection does not create charges');
SELECT is((SELECT status FROM public.rental_applications WHERE id=current_setting('test.second')::uuid),'rejected','other candidates notified and closed');
SELECT set_config('request.jwt.claims','{}',true);
SET LOCAL ROLE anon;
SELECT ok(public.public_listing(current_setting('test.public_id')::uuid) IS NULL,'selected offer no longer public');
SELECT is((SELECT count(*) FROM storage.objects WHERE bucket_id='listing-photos'),0::bigint,'selected offer cannot issue new photo links');
RESET ROLE;
SELECT set_config('request.jwt.claims','{"sub":"f1000000-0000-0000-0000-000000000001"}',true);
SET LOCAL ROLE authenticated;
SELECT throws_ok($$SELECT public.act_on_property_listing(current_setting('test.listing')::uuid,'publish',pg_temp.listing_rev())$$,'23514',NULL,'cannot advertise accepted space while draft awaits signing');
SELECT throws_ok($$SELECT public.act_on_rental_application(current_setting('test.application')::uuid,'undo_selection',3,'{}')$$,'23514',NULL,'undo requires reason');
SELECT lives_ok($$SELECT public.act_on_rental_application(current_setting('test.application')::uuid,'undo_selection',3,'{"public_note":"Candidate changed plans"}')$$,'owner can undo selection before preparing contract');
SELECT is(public.property_hub('f2000000-0000-0000-0000-000000000001')->'listings'->0->>'status','paused','undo never automatically republishes');
SELECT lives_ok($$SELECT public.act_on_property_listing(current_setting('test.listing')::uuid,'publish',pg_temp.listing_rev())$$,'owner explicitly reopens offer');
SELECT public.act_on_property_listing(current_setting('test.listing')::uuid,'pause',pg_temp.listing_rev());
SELECT ok(public.public_listing(current_setting('test.public_id')::uuid) IS NULL,'pause immediately removes public snapshot');
RESET ROLE;
SELECT set_config('request.jwt.claims','{}',true);
SET LOCAL ROLE anon;
SELECT is((SELECT count(*) FROM storage.objects WHERE bucket_id='listing-photos'),0::bigint,'pause stops new signed photo links');
RESET ROLE;
INSERT INTO public.lease_agreements(owner_id,property_id,unit_id,tenant_id,start_date,end_date,monthly_payment,status,signed_document_file)
 SELECT 'f1000000-0000-0000-0000-000000000001','f2000000-0000-0000-0000-000000000001','f3000000-0000-0000-0000-000000000001',tenant_id,CURRENT_DATE,CURRENT_DATE+365,10000,'active','owner/occupied.pdf'
 FROM public.lease_agreements WHERE id=current_setting('test.lease')::uuid;
SELECT set_config('request.jwt.claims','{"sub":"f1000000-0000-0000-0000-000000000001"}',true);
SET LOCAL ROLE authenticated;
SELECT throws_ok($$SELECT public.act_on_property_listing(current_setting('test.listing')::uuid,'publish',pg_temp.listing_rev())$$,'23514',NULL,'whole-property publication conflicts with an occupied unit');
SELECT lives_ok($$SELECT public.save_property_listing('f2000000-0000-0000-0000-000000000001',current_setting('test.listing')::uuid,null,current_setting('test.listing_values')::jsonb||jsonb_build_object('available_from',CURRENT_DATE+366,'photos',jsonb_build_array(current_setting('test.photo'))),pg_temp.listing_rev())$$,'owner can prepare future availability after existing lease');
SELECT lives_ok($$SELECT public.act_on_property_listing(current_setting('test.listing')::uuid,'publish',pg_temp.listing_rev())$$,'future availability beyond occupied unit lease is publishable');
SELECT throws_ok($$UPDATE public.properties SET owner_id='f1000000-0000-0000-0000-000000000005' WHERE id='f2000000-0000-0000-0000-000000000001'$$,'23514',NULL,'ownership transfer cannot expose applicant history');
RESET ROLE;
UPDATE public.team_memberships SET status='revoked' WHERE id='f4000000-0000-0000-0000-000000000001';
SELECT set_config('request.jwt.claims','{"sub":"f1000000-0000-0000-0000-000000000002"}',true);
SET LOCAL ROLE authenticated;
SELECT throws_ok($$SELECT public.property_hub('f2000000-0000-0000-0000-000000000001')$$,'42501',NULL,'revocation removes hub access immediately');
SELECT throws_ok($$SELECT public.act_on_rental_application(current_setting('test.second')::uuid,'note',2,'{}')$$,'42501',NULL,'revocation removes contact action access');
RESET ROLE;
SELECT * FROM finish();
ROLLBACK;
